// The six orders, as generated by the real encoder. Every home step reads them from here.
import { ORDERS_TEXT } from '../data/generated.ts';
import { SAMPLES } from '../data/samples.ts';
import { highlight, jsonKeyTally, tables, tersetKeyTally } from './format.ts';
import type { Table } from './format.ts';

export const ORDERS_VALUE = SAMPLES.orders;
export const ORDERS_COMPACT: string = ORDERS_TEXT.compact;
export const ORDERS_TERSET: string = ORDERS_TEXT.terset;
export const ORDERS_RULES: string = ORDERS_TEXT.rules;
export const ORDERS_RULES_TOKENS: number = ORDERS_TEXT.rulesTokens;
export const ORDERS_TOON: string = ORDERS_TEXT.toon;
/** The orders, colored and with columns lined up. One call measures the whole table, so a view may split it by line. */
export const ORDERS_HL: string = highlight(ORDERS_TERSET, { align: true });
export const ORDERS_LINES: readonly string[] = ORDERS_TERSET.split('\n');

const table = tables(ORDERS_TERSET)[0];
if (table === undefined) throw new Error('The orders sample no longer encodes as a table');
export const ORDERS_TABLE: Table = table;
export const ORDERS_COUNT: number = ORDERS_TABLE.rows.length;

/** How many times each key name is written, as JSON and as Terset, in JSON's first-seen order. */
export const ORDERS_TALLY: readonly { readonly key: string; readonly json: number; readonly terset: number }[] = (() => {
  const terset = tersetKeyTally(ORDERS_TERSET);
  return [...jsonKeyTally(ORDERS_VALUE)].map(([key, json]) => ({ key, json, terset: terset.get(key) ?? 0 }));
})();

/** One [indent, length] pair per TOON line, for the line silhouette. */
export const TOON_SHAPE: readonly (readonly [number, number])[] = ORDERS_TOON.split('\n').map((line) => {
  const indent = line.length - line.trimStart().length;
  return [indent, line.length - indent] as const;
});
